import{_ as s,o as a,c as i,ae as t}from"./chunks/framework.Co1PSFSm.js";const c=JSON.parse('{"title":"","description":"Fresh has built-in OpenTelemetry instrumentation for tracing requests through middleware, handlers, and rendering.\\n","frontmatter":{"description":"Fresh has built-in OpenTelemetry instrumentation for tracing requests through middleware, handlers, and rendering.\\n"},"headers":[],"relativePath":"en/advanced/opentelemetry.md","filePath":"en/advanced/opentelemetry.md"}'),n={name:"en/advanced/opentelemetry.md"};function l(r,e,h,p,o,d){return a(),i("div",null,[...e[0]||(e[0]=[t(`<p>Fresh automatically instruments key operations with <a href="https://opentelemetry.io/" target="_blank" rel="noreferrer">OpenTelemetry</a> spans, giving you visibility into how requests flow through your application. No code changes are needed - just configure an exporter.</p><h2 id="what-s-instrumented" tabindex="-1">What&#39;s instrumented <a class="header-anchor" href="#what-s-instrumented" aria-label="Permalink to &quot;What&#39;s instrumented&quot;">​</a></h2><p>Fresh creates spans for:</p><ul><li><strong><a href="/docs/concepts/middleware.html">Middleware</a> execution</strong> - each middleware in the chain</li><li><strong>Route handler execution</strong> - handler function calls</li><li><strong>Rendering</strong> - server-side page rendering, including async components</li><li><strong><a href="/docs/concepts/static-files.html">Static file</a> serving</strong> - file lookups, caching, and responses</li><li><strong>Lazy route loading</strong> - dynamic imports of route modules on first access</li></ul><p>All spans are created under the <code>fresh</code> tracer (named with the current Fresh version). The root span for each request includes <code>http.route</code> with the matched route pattern (e.g. <code>GET /blog/:slug</code>), making it easy to group traces by route.</p><h2 id="enabling-tracing" tabindex="-1">Enabling tracing <a class="header-anchor" href="#enabling-tracing" aria-label="Permalink to &quot;Enabling tracing&quot;">​</a></h2><p>Fresh uses the <code>@opentelemetry/api</code> package (the vendor-neutral API). Spans are created automatically - you just need to provide an OpenTelemetry SDK and exporter to collect them.</p><p>If no exporter is configured, the spans are silently discarded with no performance overhead.</p><h3 id="with-deno-s-built-in-opentelemetry" tabindex="-1">With Deno&#39;s built-in OpenTelemetry <a class="header-anchor" href="#with-deno-s-built-in-opentelemetry" aria-label="Permalink to &quot;With Deno&#39;s built-in OpenTelemetry&quot;">​</a></h3><p>Deno has <a href="https://docs.deno.com/runtime/fundamentals/open_telemetry/" target="_blank" rel="noreferrer">built-in OpenTelemetry support</a>. Enable it with the <code>OTEL_DENO</code> environment variable:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OTEL_DENO</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> deno</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>This exports traces to an OTLP-compatible collector. Configure the endpoint:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OTEL_DENO</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OTEL_EXPORTER_OTLP_ENDPOINT=http://localhost:4317 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">deno </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><h3 id="with-deno-deploy" tabindex="-1">With Deno Deploy <a class="header-anchor" href="#with-deno-deploy" aria-label="Permalink to &quot;With Deno Deploy&quot;">​</a></h3><p><a href="/docs/deployment/deno-deploy.html">Deno Deploy</a> collects Fresh traces automatically when using the Fresh preset - no configuration needed. Traces appear in the Deno Deploy dashboard.</p><h3 id="with-a-custom-exporter" tabindex="-1">With a custom exporter <a class="header-anchor" href="#with-a-custom-exporter" aria-label="Permalink to &quot;With a custom exporter&quot;">​</a></h3><p>You can use any OpenTelemetry-compatible backend (Jaeger, Zipkin, Honeycomb, Grafana Tempo, Datadog, etc.). Install the SDK and configure an exporter in your entry point:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { NodeSDK } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@opentelemetry/sdk-node&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { OTLPTraceExporter } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;@opentelemetry/exporter-trace-otlp-http&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> sdk</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> NodeSDK</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  traceExporter: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> OTLPTraceExporter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    url: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://your-collector.example.com/v1/traces&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sdk.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">start</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><h2 id="span-attributes" tabindex="-1">Span attributes <a class="header-anchor" href="#span-attributes" aria-label="Permalink to &quot;Span attributes&quot;">​</a></h2><p>Fresh sets the following attributes on spans:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Span type</th><th>Description</th></tr></thead><tbody><tr><td><code>http.route</code></td><td>Root</td><td>The matched route pattern (e.g. <code>/blog/:slug</code>)</td></tr><tr><td><code>fresh.span_type</code></td><td>Various</td><td>Internal span classification (<code>render</code>, etc.)</td></tr><tr><td><code>fresh.cache</code></td><td>Static file</td><td>Cache status (<code>immutable</code>, <code>not_modified</code>, <code>no_cache</code>, <code>invalid_bust_key</code>)</td></tr><tr><td><code>fresh.cache_key</code></td><td>Static file</td><td>The cache bust key for the asset</td></tr></tbody></table><p>Errors in handlers or rendering are recorded on the span with <code>span.recordException()</code> and the span status is set to <code>ERROR</code>.</p><h2 id="local-development" tabindex="-1">Local development <a class="header-anchor" href="#local-development" aria-label="Permalink to &quot;Local development&quot;">​</a></h2><h3 id="console-exporter" tabindex="-1">Console exporter <a class="header-anchor" href="#console-exporter" aria-label="Permalink to &quot;Console exporter&quot;">​</a></h3><p>The quickest way to see traces is to print them to the console. Deno (2.7+) supports this out of the box - no extra dependencies or services needed:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OTEL_DENO</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OTEL_TRACES_EXPORTER=console </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">deno </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>Each request prints its spans directly to stderr, showing the full breakdown of middleware, handler, and rendering timings.</p><h3 id="jaeger" tabindex="-1">Jaeger <a class="header-anchor" href="#jaeger" aria-label="Permalink to &quot;Jaeger&quot;">​</a></h3><p>For a visual trace explorer, run <a href="https://www.jaegertracing.io/" target="_blank" rel="noreferrer">Jaeger</a> locally with Docker:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jaeger</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 16686:16686</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 4317:4317</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  jaegertracing/all-in-one:latest</span></span></code></pre></div><p>Then start your Fresh app pointing at the Jaeger collector:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OTEL_DENO</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OTEL_EXPORTER_OTLP_ENDPOINT=http://localhost:4317 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">deno </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>Open <code>http://localhost:16686</code> to browse traces. You&#39;ll see each request broken down into its middleware, handler, and rendering spans.</p><h2 id="client-side-trace-correlation" tabindex="-1">Client-side trace correlation <a class="header-anchor" href="#client-side-trace-correlation" aria-label="Permalink to &quot;Client-side trace correlation&quot;">​</a></h2><p>When an OpenTelemetry exporter is active, Fresh automatically injects a <a href="https://www.w3.org/TR/trace-context/" target="_blank" rel="noreferrer">W3C Trace Context</a> <code>&lt;meta&gt;</code> tag into the <code>&lt;head&gt;</code> of every rendered page:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">head</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">meta</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;traceparent&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    content</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;00-ab42124a3c573678d4d8b21ba52df3bf-d21f7bc17caa5aba-01&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  &lt;!-- ... --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">head</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>This allows client-side OpenTelemetry instrumentation (such as <a href="https://github.com/open-telemetry/opentelemetry-js-contrib/tree/c9d62be989802534c01373e8ab41e13747d7ee3e/packages/instrumentation-document-load" target="_blank" rel="noreferrer"><code>@opentelemetry/instrumentation-document-load</code></a>) to link browser performance traces back to the server-side span that rendered the page, giving you end-to-end visibility from server rendering through page load.</p>`,37)])])}const g=s(n,[["render",l]]);export{c as __pageData,g as default};
